import CryptoKit
import Foundation

// Clipboard history: the pure part. Classification of what is on a pasteboard, the
// privacy rules (concealed / transient / auto-generated markers, ignored apps), and the
// history list (de-duplication, caps, age, pins, search). No AppKit here; the monitor
// (`ShelfClipboardMonitor`) reads the pasteboard and feeds these functions.

/// What a clip holds.
nonisolated enum ShelfClipKind: String, Codable, Sendable, CaseIterable {
    case text
    /// Styled text: kept as plain text plus RTF.
    case richText = "rich-text"
    case url
    /// References to files or folders (paths), never copies.
    case files
    case image

    /// SF Symbol shown at the row's leading edge.
    var symbol: String {
        switch self {
        case .text: "text.alignleft"
        case .richText: "textformat"
        case .url: "link"
        case .files: "doc"
        case .image: "photo"
        }
    }
}

/// Pasteboard type identifiers the rules look at (strings, so the pure code needs no AppKit).
nonisolated enum ShelfPasteboardTypes {
    static let string = "public.utf8-plain-text"
    static let rtf = "public.rtf"
    static let rtfd = "com.apple.flat-rtfd"
    static let url = "public.url"
    static let fileURL = "public.file-url"
    static let png = "public.png"
    static let tiff = "public.tiff"
    /// nspasteboard.org markers: never record these.
    static let concealed = "org.nspasteboard.ConcealedType"
    static let transient = "org.nspasteboard.TransientType"
    static let autoGenerated = "org.nspasteboard.AutoGeneratedType"
    /// nspasteboard.org: the bundle id of the app that wrote the item, when it says so.
    static let source = "org.nspasteboard.source"
    /// Older markers some apps still write instead of the nspasteboard.org ones.
    static let legacyTransient = ["de.petermaurer.TransientPasteboardType", "com.typeit4me.clipping", "Pasteboard generator type"]
    static let legacyConcealed = ["net.antelle.keeweb"]
}

/// Why something on the pasteboard was not recorded. Logged by reason only, never with content.
nonisolated enum ShelfClipSkipReason: String, Error, Sendable, Equatable {
    case concealed
    case transient
    case autoGenerated = "auto-generated"
    case ignoredApp = "ignored-app"
    case empty
    case tooLarge = "too-large"
}

/// The privacy rules, applied to the pasteboard's types and the frontmost app *before* any
/// content is read, so a concealed entry is never even read.
nonisolated enum ShelfClipRules {
    /// Password managers and similar apps whose copies are never recorded (user-editable).
    static let defaultIgnoredApps: [String] = [
        "com.apple.Passwords",
        "com.apple.keychainaccess",
        "com.1password.1password",
        "com.agilebits.onepassword7",
        "com.agilebits.onepassword-osx",
        "com.bitwarden.desktop",
        "org.keepassxc.keepassxc",
        "com.dashlane.Dashlane",
        "com.lastpass.LastPass",
        "in.sinew.Enpass-Desktop",
        "me.proton.pass.electron",
        "com.markmcguill.strongbox.mac",
        "com.nordpass.macos.NordPass",
        "com.keepersecurity.passwordmanager",
    ]

    static func skipReason(types: [String], frontmostBundleID: String?, ignoredApps: Set<String>) -> ShelfClipSkipReason? {
        if types.isEmpty { return .empty }
        let set = Set(types)
        if set.contains(ShelfPasteboardTypes.concealed) || !set.isDisjoint(with: ShelfPasteboardTypes.legacyConcealed) {
            return .concealed
        }
        if set.contains(ShelfPasteboardTypes.transient) || !set.isDisjoint(with: ShelfPasteboardTypes.legacyTransient) {
            return .transient
        }
        if set.contains(ShelfPasteboardTypes.autoGenerated) { return .autoGenerated }
        if let frontmostBundleID, ignoredApps.contains(frontmostBundleID) { return .ignoredApp }
        return nil
    }
}

/// What the monitor read from the pasteboard (only after the rules allowed it).
nonisolated struct ShelfPasteboardContent: Sendable, Equatable {
    var plainText: String?
    var rtf: Data?
    /// From `public.url` (a link copied as a link).
    var url: String?
    /// File URLs as paths.
    var filePaths: [String] = []
    /// PNG data, already size-capped by the monitor.
    var image: Data?
    var imagePixelSize: CGSize?
    /// The app named by `org.nspasteboard.source`, when the writer set it.
    var declaredSource: String?
}

/// A clip ready to enter the history.
nonisolated struct ShelfClipCandidate: Sendable, Equatable {
    var kind: ShelfClipKind
    var text: String?
    var rtf: Data?
    var url: String?
    var filePaths: [String]?
    var image: Data?
    var imagePixelSize: CGSize?
    /// Identity for de-duplication: same kind and same primary content.
    var fingerprint: String
}

nonisolated enum ShelfClipClassifier {
    /// Longest plain text recorded (characters); longer copies are skipped.
    static let maxTextLength = 500_000
    /// RTF beyond this is dropped; the plain text stays.
    static let maxRTFBytes = 1_000_000

    /// Files win (a Finder copy also carries the names as text); then text (a link becomes
    /// `.url`, styled text `.richText`); an image only when there is no text (Office and
    /// Keynote copies carry a picture of the selection next to the text).
    static func candidate(from content: ShelfPasteboardContent) -> Result<ShelfClipCandidate, ShelfClipSkipReason> {
        if !content.filePaths.isEmpty {
            let paths = content.filePaths
            return .success(ShelfClipCandidate(kind: .files, filePaths: paths,
                                               fingerprint: fingerprint(.files, paths.joined(separator: "\n"))))
        }
        let text = content.plainText.flatMap { $0.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty ? nil : $0 }
        if let link = content.url.flatMap(webURL) ?? text.flatMap(webURL) {
            return .success(ShelfClipCandidate(kind: .url, text: text, url: link, fingerprint: fingerprint(.url, link)))
        }
        if let text {
            guard text.count <= maxTextLength else { return .failure(.tooLarge) }
            if let rtf = content.rtf, rtf.count <= maxRTFBytes {
                // Styled and plain copies of the same words are one clip.
                return .success(ShelfClipCandidate(kind: .richText, text: text, rtf: rtf, fingerprint: fingerprint(.text, text)))
            }
            return .success(ShelfClipCandidate(kind: .text, text: text, fingerprint: fingerprint(.text, text)))
        }
        if let image = content.image {
            return .success(ShelfClipCandidate(kind: .image, image: image, imagePixelSize: content.imagePixelSize,
                                               fingerprint: fingerprint(.image, SHA256.hash(data: image).hexString)))
        }
        if let link = content.url {
            // A non-web URL without text (mailto:, a custom scheme).
            return .success(ShelfClipCandidate(kind: .url, url: link, fingerprint: fingerprint(.url, link)))
        }
        return .failure(.empty)
    }

    /// The text is exactly one absolute URL with a scheme and host (or `mailto:`).
    static func webURL(_ raw: String) -> String? {
        let trimmed = raw.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmed.isEmpty, trimmed.count < 4096, !trimmed.contains(where: \.isWhitespace),
              let components = URLComponents(string: trimmed), let scheme = components.scheme?.lowercased() else { return nil }
        if scheme == "mailto" { return trimmed }
        guard ["http", "https", "ftp"].contains(scheme), let host = components.host, !host.isEmpty else { return nil }
        return trimmed
    }

    static func fingerprint(_ kind: ShelfClipKind, _ content: String) -> String {
        // Rich and plain text share the `.text` namespace so styling alone does not duplicate.
        let namespace = kind == .richText ? ShelfClipKind.text.rawValue : kind.rawValue
        return SHA256.hash(data: Data((namespace + "\u{0}" + content).utf8)).hexString
    }
}

/// One entry of the history, as stored on disk.
nonisolated struct ShelfClip: Codable, Sendable, Identifiable, Equatable {
    /// Opaque and stable: also the id of the clip's palette row (never derived from content).
    var id: UUID
    var kind: ShelfClipKind
    var text: String?
    var rtf: Data?
    var url: String?
    var filePaths: [String]?
    /// File name of the stored PNG inside the store's image folder.
    var imageFile: String?
    var imagePixelWidth: Double?
    var imagePixelHeight: Double?
    var sourceBundleID: String?
    var firstCopied: Date
    var lastCopied: Date
    var isPinned = false
    var fingerprint: String

    /// One line for the row: the first non-empty line, whitespace collapsed.
    var preview: String {
        switch kind {
        case .text, .richText:
            return Self.oneLine(text ?? "")
        case .url:
            return url ?? Self.oneLine(text ?? "")
        case .files:
            let names = (filePaths ?? []).map { ($0 as NSString).lastPathComponent }
            guard let first = names.first else { return "" }
            return names.count == 1 ? first : String(localized: "\(first) and \(names.count - 1) more", table: "Shelf")
        case .image:
            if let width = imagePixelWidth, let height = imagePixelHeight {
                return String(localized: "Image \(Int(width)) × \(Int(height))", table: "Shelf")
            }
            return String(localized: "Image", table: "Shelf")
        }
    }

    /// Text the search field matches.
    var searchableText: String {
        [text, url, filePaths?.map { ($0 as NSString).lastPathComponent }.joined(separator: " ")]
            .compactMap { $0 }.joined(separator: " ")
    }

    static func oneLine(_ text: String, limit: Int = 240) -> String {
        let line = text.split(whereSeparator: \.isNewline)
            .first { !$0.trimmingCharacters(in: .whitespaces).isEmpty }.map(String.init) ?? ""
        let collapsed = line.split(whereSeparator: \.isWhitespace).joined(separator: " ")
        return collapsed.count > limit ? String(collapsed.prefix(limit)) + "…" : collapsed
    }
}

/// The history list: newest first. Pure value; the controller persists it.
nonisolated struct ShelfClipHistory: Codable, Sendable, Equatable {
    private(set) var clips: [ShelfClip] = []

    init(clips: [ShelfClip] = []) {
        self.clips = clips.sorted { $0.lastCopied > $1.lastCopied }
    }

    enum RecordOutcome: Equatable {
        case inserted(UUID)
        /// The same content was already there: it moved to the top.
        case moved(UUID)
    }

    /// Adds a clip or, when the same content is already in the history, moves that one to
    /// the top (keeping its pin and first-copied date). `imageFile` names the stored image.
    @discardableResult
    mutating func record(_ candidate: ShelfClipCandidate, source: String?, imageFile: String? = nil, now: Date,
                         id: UUID = UUID()) -> RecordOutcome {
        if let index = clips.firstIndex(where: { $0.fingerprint == candidate.fingerprint }) {
            var clip = clips.remove(at: index)
            clip.lastCopied = now
            if clip.kind == .text, candidate.kind == .richText { clip.kind = .richText; clip.rtf = candidate.rtf }
            if let source { clip.sourceBundleID = source }
            clips.insert(clip, at: 0)
            return .moved(clip.id)
        }
        let clip = ShelfClip(id: id, kind: candidate.kind, text: candidate.text, rtf: candidate.rtf, url: candidate.url,
                             filePaths: candidate.filePaths, imageFile: imageFile,
                             imagePixelWidth: candidate.imagePixelSize.map { Double($0.width) },
                             imagePixelHeight: candidate.imagePixelSize.map { Double($0.height) },
                             sourceBundleID: source, firstCopied: now, lastCopied: now, fingerprint: candidate.fingerprint)
        clips.insert(clip, at: 0)
        return .inserted(id)
    }

    /// Moves a clip to the top (it was copied back from the shelf).
    mutating func touch(_ id: UUID, now: Date) {
        guard let index = clips.firstIndex(where: { $0.id == id }) else { return }
        var clip = clips.remove(at: index)
        clip.lastCopied = now
        clips.insert(clip, at: 0)
    }

    /// Applies the caps: unpinned clips older than `maxAge`, and unpinned clips beyond
    /// `limit` (counting newest first). Pinned clips are exempt from both. Returns what left.
    @discardableResult
    mutating func prune(now: Date, limit: Int, maxAge: TimeInterval) -> [ShelfClip] {
        var kept: [ShelfClip] = []
        var removed: [ShelfClip] = []
        var unpinned = 0
        for clip in clips {
            if clip.isPinned { kept.append(clip); continue }
            if now.timeIntervalSince(clip.lastCopied) > maxAge || unpinned >= max(0, limit) {
                removed.append(clip)
            } else {
                unpinned += 1
                kept.append(clip)
            }
        }
        clips = kept
        return removed
    }

    mutating func setPinned(_ id: UUID, _ pinned: Bool) {
        guard let index = clips.firstIndex(where: { $0.id == id }) else { return }
        clips[index].isPinned = pinned
    }

    @discardableResult
    mutating func delete(_ id: UUID) -> ShelfClip? {
        guard let index = clips.firstIndex(where: { $0.id == id }) else { return nil }
        return clips.remove(at: index)
    }

    /// "Clear history": every clip except pinned ones. Returns what left.
    @discardableResult
    mutating func clearUnpinned() -> [ShelfClip] {
        let removed = clips.filter { !$0.isPinned }
        clips.removeAll { !$0.isPinned }
        return removed
    }

    /// Everything, pinned too (the history was turned off).
    @discardableResult
    mutating func removeAll() -> [ShelfClip] {
        defer { clips = [] }
        return clips
    }

    func clip(_ id: UUID) -> ShelfClip? { clips.first { $0.id == id } }

    /// What the panel lists: pinned first, then newest first; filtered by every word of
    /// `query` (case and diacritics ignored).
    func visible(matching query: String) -> [ShelfClip] {
        let words = query.split(whereSeparator: \.isWhitespace).map(String.init)
        let matched = words.isEmpty ? clips : clips.filter { clip in
            let haystack = clip.searchableText
            return words.allSatisfy { haystack.range(of: $0, options: [.caseInsensitive, .diacriticInsensitive]) != nil }
        }
        return matched.filter(\.isPinned) + matched.filter { !$0.isPinned }
    }
}

nonisolated private extension Digest {
    var hexString: String { map { String(format: "%02x", $0) }.joined() }
}
